'use strict';const M=Model,U=OmniUI,$=x=>document.getElementById(x);let unlocked=false,demo=false,current=null,epoch=0,busy=false,queued=false;function clearDisplay(){current=null;$('code').textContent='••• •••';$('countdown').textContent='';$('label').textContent=unlocked?($('account').selectedOptions[0]?.textContent||''):'Vault locked'}function hide(){epoch++;queued=false;unlocked=false;demo=false;current=null;$('code').textContent='••• •••';$('countdown').textContent='';$('label').textContent='Vault locked';$('account').replaceChildren();$('enroll').disabled=true;$('account').disabled=true}async function reveal(){if(!unlocked||!$('account').value)return;if(busy){queued=true;return}busy=true;queued=false;const e=epoch,id=$('account').value,label=$('account').selectedOptions[0].textContent;clearDisplay();try{const result=await U.request('vault.totp.code',{accountId:id});if(e!==epoch||id!==$('account').value||!unlocked||document.hidden)return;const c=M.code(result);current=c;$('code').textContent=c.code;$('label').textContent=label}catch(_){if(e===epoch&&id===$('account').value&&unlocked&&!document.hidden){hide();U.notify('Code unavailable. Vault locked.')}}finally{busy=false;if(queued&&unlocked&&!document.hidden){queued=false;reveal()}}}async function unlock(){hide();const e=epoch;try{const cap=M.capability(await U.request('vault.capabilities',{}));if(!cap.unlocked&&!M.capability(await U.request('vault.unlock',{})).unlocked)throw Error('Locked');const list=M.accounts(await U.request('vault.totp.list',{}));if(e!==epoch)return;unlocked=true;$('enroll').disabled=false;$('account').disabled=false;for(const x of list){const o=document.createElement('option');o.value=x.id;o.textContent=x.label;$('account').append(o)}U.notify('Secure vault unlocked.');await reveal()}catch(_){hide();U.notify('An encrypted vault with protected keys is required. Existing obfuscated storage is not supported.')}}$('unlock').onclick=unlock;$('account').onchange=()=>{epoch++;clearDisplay();reveal()};$('enroll').onclick=async()=>{if(!unlocked)return;try{const r=await U.request('vault.totp.enroll',{});if(r?.saved!==true)throw Error();await unlock()}catch(_){U.notify('Account was not confirmed saved.')}};$('lock').onclick=()=>{hide();U.request('vault.lock',{}).catch(()=>{});U.notify('Codes hidden. Native lock requested.')};$('demo').onclick=async()=>{hide();const e=epoch;try{const seed=new TextEncoder().encode('12345678901234567890');let c;try{c=await M.totp(seed,{time:59,digits:8})}finally{seed.fill(0)}if(e!==epoch)return;demo=true;$('label').textContent='Public RFC 6238 test vector';$('code').textContent=c;$('countdown').textContent='Fixed example at Unix time 59 · not a real account';U.notify('Public test example only. No secret was saved.')}catch(_){U.notify('Reference cryptography unavailable in this browser.')}};const timer=setInterval(()=>{if(current){const left=Math.ceil((current.validUntil-Date.now())/1000);if(left<=0){clearDisplay();reveal()}else $('countdown').textContent='New code in '+left+' seconds'}},1000);document.addEventListener('visibilitychange',()=>{if(document.hidden)hide()});window.addEventListener('blur',hide);window.addEventListener('pagehide',()=>{hide();clearInterval(timer)});window.addEventListener('omni-vault-locked',hide);hide();U.focus($('unlock'));
